#!/usr/bin/env bash
set -u
# СУДИТ: hooks/tests/costly-justified.tsv scripts/costly-tests.sh
# probe_D1232 — у каждого теста, чья цена поодиночке выше порога, есть строка оправдания с числом и причиной: прибор
#   `scripts/costly-tests.sh` на последнем замере (`state/suite-cost.tsv`, пишет его режим `--measure`) с реестром ЭТОГО
#   дерева не называет ни «ДОРОГИЕ БЕЗ ОПРАВДАНИЯ», ни «РЕЕСТР УСТАРЕЛ». Различает прибор сам: проба D460 судит его
#   на синтетическом замере, эта — мир.
#   0 — находок нет; 1 — прибор назвал находки (выведены); 2 — замера нет или прибора нет.
cd "${CLAUDSOUL_REPO:-$(git rev-parse --show-toplevel 2>/dev/null)}" 2>/dev/null || exit 2
[ -f scripts/costly-tests.sh ] || exit 2
out=$(CLAUDSOUL_REPO="$PWD" bash scripts/costly-tests.sh 2>&1); rc=$?
[ "$rc" = 2 ] && { printf '%s\n' "$out"; exit 2; }
# Код 0 засчитывается только со словами прибора (D1222: выпотрошенный прибор отвечал 0, и проба зеленела — она верила
# одному коду): «дорогих без оправдания нет, реестр свеж» печатает лишь честный прогон проверки.
[ "$rc" = 0 ] && grep -q 'дорогих без оправдания нет, реестр свеж' <<< "$out" && exit 0
[ "$rc" = 0 ] && { echo "прибор ответил 0 без своей итоговой строки — не судил"; exit 1; }
printf '%s\n' "$out" | grep -A8 'БЕЗ ОПРАВДАНИЯ\|УСТАРЕЛ'
exit 1
